function lineHomework(rows){return rows.length?`<div class="line-list">${rows.map(h=>`<div class="line-row"><span class="avatar">${icon('homework',17)}</span><div class="line-content"><div class="line-title">${esc(h.title||'과제')} ${badge(h.status)}</div><div class="line-description ${h.overdue?'red':''}">${h.overdue?'제출 기한이 지났습니다 · ':''}${timeText(h.due_at)}까지 · ${esc(h.lesson.homework)}</div></div><div class="line-actions">${btn(h.submission?'제출 내역':'과제 제출','homework-detail',`data-id="${h.id}"`,h.submission?'sm':'primary sm')}</div></div>`).join('')}</div>`:empty('확인할 과제가 없습니다.')}
function studentCell(s){if(['students','reports'].includes(S.view))s={...s,student_no:''};return`<div class="flex"><span class="avatar">${esc(s.name.slice(-2))}</span><span><span class="primary-text">${esc(s.name)}</span><small>${esc(s.student_no||'')}</small></span></div>`}
