function newConsult(){const requestID=crypto.randomUUID();modal('상담 신청',`<form id="consult-form">${fieldsHtml([{key:'class_id',label:'강좌',type:'select',options:classOptions(),default:currentClass(),required:true,wide:true},{key:'category',label:'상담 주제',type:'select',options:['학습 · 성적','숙제 · 학습 습관','수업 · 반 이동','진학 · 진로','출결 · 일정','기타']},{key:'contact_method',label:'희망 상담 방법',type:'select',options:['전화 상담','대면 상담','메시지']},{key:'preferred_at',label:'희망 일시',type:'datetime-local',wide:true},{key:'reason',label:'상담 내용',type:'textarea',required:true,wide:true,rows:5,placeholder:'상담하고 싶은 내용을 적어 주세요.'}])}</form>`,btn('신청하기','save-editor','','primary','consultations'));M.save=async()=>{if(!$('#consult-form').reportValidity())return;const d=collect();d.request_id=requestID;d.preferred_at=toISO(d.preferred_at);try{await api('/api/consultations',{method:'POST',body:d});closeModal(true);await reload();toast('상담을 신청했습니다.')}catch(e){errorBox(e.message)}}}
function consultDetail(id){const c=S.data.consultations.find(x=>x.id===id);if(!c)return;const staff=!isFamily(),editable=staff&&can('consultation_edit');modal(getStudent(c.student_id).name+' · 상담',`<div class="tagline">${badge(c.status)}<span>${esc(c.category)} · ${esc(c.contact_method)}</span></div><small>${timeText(c.created_at)} 신청 · ${esc(getClass(c.class_id).name)}</small><p class="preline detail-text">${esc(c.reason)}</p>${editable?fieldsHtml([{key:'status',label:'처리 상태',type:'select',options:['requested','scheduled','completed','cancelled'].map(s=>[s,badges[s][0]])},{key:'preferred_at',label:'상담 일시',type:'datetime-local'},{key:'staff_reply',label:'학부모에게 보이는 답변',type:'textarea',wide:true,rows:4},{key:'private_note',label:'강사용 메모',type:'textarea',wide:true}],{...c,preferred_at:localTime(c.preferred_at)}):`<div class="detail-section"><h3>희망 상담 일시</h3><p>${timeText(c.preferred_at)}</p></div><div class="detail-section"><h3>선생님의 답변</h3><p class="preline">${esc(c.staff_reply)||'선생님이 확인 중입니다.'}</p></div>`}`,editable?btn('저장','save-editor','','primary','check'):!staff&&['requested','scheduled'].includes(c.status)?btn('신청 취소','cancel-consult',`data-id="${c.id}"`,'danger'):'',{drawer:true});if(staff&&can('consultation_delete')){let footer=M.node.querySelector('.modal-footer');if(!footer){footer=document.createElement('footer');footer.className='modal-footer';M.node.querySelector('.modal').append(footer)}footer.insertAdjacentHTML('afterbegin',btn('상담 삭제','consult-delete',`data-id="${c.id}"`,'danger'));}if(staff)window.MiraePolish.readConsultation(c).catch(e=>toast(e.message,true));if(editable)M.save=async()=>{if(M.busy)return;const editor=M;editor.busy=true;try{const d=collect();d.preferred_at=toISO(d.preferred_at);await saveChunks('consultations',[{id:c.id,version:c.version,...d}]);closeModal(true);await reload();toast('상담 내용을 저장했습니다.')}catch(e){errorBox(e.message)}finally{editor.busy=false}}}
let ytPromise=null;
function loadYouTube(){if(window.YT?.Player)return Promise.resolve(window.YT);if(ytPromise)return ytPromise;ytPromise=new Promise((resolve,reject)=>{window.onYouTubeIframeAPIReady=()=>resolve(window.YT);const s=document.createElement('script');s.src='https://www.youtube.com/iframe_api';s.onerror=()=>{ytPromise=null;reject(Error('YouTube에 연결하지 못했습니다. 아래 버튼으로 시청해 주세요.'))};document.head.append(s);setTimeout(()=>{if(!window.YT?.Player){ytPromise=null;reject(Error('YouTube 응답이 늦어지고 있습니다. 아래 버튼으로 시청해 주세요.'))}},15000)});return ytPromise}
function saveVideoProgress(){if(!currentPlayer?.getCurrentTime||!playerVideo||!isFamily())return;let position,duration;try{position=currentPlayer.getCurrentTime();duration=currentPlayer.getDuration()}catch{return}if(Number.isFinite(position)&&Number.isFinite(duration)&&duration>0)api('/api/video-progress',{method:'POST',body:{video_id:playerVideo.id,position_seconds:position,duration_seconds:duration}}).catch(()=>{})}
function stopPlayer(){clearInterval(playTimer);playTimer=null;saveVideoProgress();try{currentPlayer?.stopVideo?.();currentPlayer?.destroy?.()}catch{}currentPlayer=null;playerVideo=null}
const ytLogo='<svg width="27" height="20" viewBox="0 0 28 20" aria-label="YouTube"><path fill="#ff0033" d="M27.4 3.1C27.1 1.7 26.1.7 24.7.4 22.4 0 14 0 14 0S5.6 0 3.3.4C1.9.7.9 1.7.6 3.1 0 5.4 0 10 0 10s0 4.6.6 6.9c.3 1.4 1.3 2.4 2.7 2.7 2.3.4 10.7.4 10.7.4s8.4 0 10.7-.4c1.4-.3 2.4-1.3 2.7-2.7.6-2.3.6-6.9.6-6.9s0-4.6-.6-6.9Z"/><path fill="white" d="m11 5.7 7.3 4.3-7.3 4.3z"/></svg>';
async function playVideo(id){const v=S.data.videos.find(x=>x.id===id);if(!v)return;stopPlayer();playerVideo=v;modal(v.title,`<div class="video-player"><div id="youtube-player"></div></div><p id="video-message" class="muted"></p><div class="video-bottom"><div><strong>${esc(getClass(v.class_id).name)}</strong><small>${dateText(v.video_date,true)}</small></div><a href="https://www.youtube.com/watch?v=${v.youtube_id}" target="_blank" rel="noopener noreferrer" id="youtube-external" class="btn youtube-btn">${ytLogo}<span>YouTube에서 시청</span>${icon('external',14)}</a></div>`,isFamily()?'':btn('영상 정보 수정','edit-video',`data-id="${v.id}"`,'','edit'),{wide:true,cleanup:stopPlayer});const node=M.node;$ ('#youtube-external',node).onclick=e=>{if(DEMO){e.preventDefault();toast('실제 운영 화면에서 등록한 강의 링크로 연결됩니다.');return}try{currentPlayer?.pauseVideo?.()}catch{}saveVideoProgress();const frame=$('iframe',node);if(frame&&!currentPlayer){frame.src='about:blank'}};if(DEMO){$('#youtube-player',node).innerHTML=`<div class="video-placeholder">${ytLogo}<strong>수업 영상 미리보기</strong><span>실제 운영에서는 등록한 YouTube 영상이 여기에서 재생됩니다.</span></div>`;return}try{await loadYouTube();if(!node.isConnected)return;const progress=S.data.video_progress.find(p=>p.video_id===id&&p.student_id===childID());currentPlayer=new YT.Player('youtube-player',{videoId:v.youtube_id,host:'https://www.youtube-nocookie.com',width:'100%',height:'100%',playerVars:{playsinline:1,rel:0,origin:location.origin},events:{onReady:e=>{if(progress?.position_seconds)e.target.seekTo(progress.position_seconds,true);playTimer=setInterval(saveVideoProgress,15000)},onError:e=>{$('#video-message',node).textContent=[101,150].includes(e.data)?'이 영상은 외부 재생이 제한되어 있습니다. YouTube에서 시청해 주세요.':'영상을 불러오지 못했습니다. YouTube에서 시청해 주세요.'}}})}catch(e){if(node.isConnected)$('#video-message',node).textContent=e.message}}
document.addEventListener('visibilitychange',()=>{if(document.hidden){saveVideoProgress();try{currentPlayer?.pauseVideo?.()}catch{}}});

function trendChart(m){const ss=m.scored;if(!ss.length)return empty('시험 결과가 쌓이면 성적 변화를 볼 수 있습니다.');const w=850,h=220,p={l:38,r:20,t:15,b:35},x=i=>ss.length===1?w/2:p.l+i/(ss.length-1)*(w-p.l-p.r),y=n=>p.t+(100-Math.max(0,Math.min(100,n)))/100*(h-p.t-p.b);const points=ss.map((s,i)=>({x:x(i),y:y(s.pct),s})),means=ss.map((s,i)=>({x:x(i),value:S.data.exam_stats[s.exam_id]?.mean==null?null:Number(S.data.exam_stats[s.exam_id].mean)/s.exam.max_score*100}));return`<div class="chart-legend"><span><i></i>학생 성적</span><span><i class="secondary"></i>반 평균</span><small>100점 환산</small></div><svg viewBox="0 0 ${w} ${h}" class="trend-chart" role="img" aria-label="시험별 학생 성적과 반 평균"><title>시험별 학생 성적과 반 평균</title>${[0,25,50,75,100].map(n=>`<line x1="${p.l}" x2="${w-p.r}" y1="${y(n)}" y2="${y(n)}" stroke="#edf0f6"/><text x="${p.l-9}" y="${y(n)+4}" text-anchor="end" fill="#8b96a9" font-size="11">${n}</text>`).join('')}<path d="${means.filter(p=>p.value!==null&&Number.isFinite(p.value)).map((p,i)=>(i?'L':'M')+p.x+','+y(p.value)).join(' ')}" fill="none" stroke="#b7c2d3" stroke-width="2" stroke-dasharray="5 5"/><path d="${points.map((p,i)=>(i?'L':'M')+p.x+','+p.y).join(' ')}" fill="none" stroke="#5276e5" stroke-width="2.6"/>${points.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="4" fill="#5276e5"><title>${esc(p.s.exam.title)}: ${fmt(p.s.pct)}점</title></circle>${(ss.length<=12||i%Math.ceil(ss.length/10)===0||i===ss.length-1)?`<text x="${p.x}" y="${h-10}" text-anchor="middle" fill="#7d889b" font-size="11">${p.s.exam.exam_date.slice(5).replace('-','/')}</text>`:''}`).join('')}</svg>`}
function studentReportHTML(id){const s=getStudent(id),m=studentMetrics(id),units={};m.scored.forEach(x=>{const k=x.exam.unit||x.exam.subject||'전체';(units[k]||=[]).push(x.pct)});const delta=m.delta===null?'—':`${m.delta>0?'+':''}${fmt(m.delta)}점`;return`<article class="report-paper" id="report-paper"><header class="report-header"><div><h2>${esc(s.name)} <span>학습 리포트</span></h2><p>${esc(s.school)} ${esc(s.grade)}</p></div><div class="report-period"><strong>${S.start} — ${S.end}</strong><small>${S.classId?esc(getClass(S.classId).name):'조회 가능한 전체 강좌'}</small></div></header>${stats([['평균 성적',fmt(m.average),'점','100점 환산 · '+m.count+'회 응시'],['성적 변화',delta,'',m.count>=6?'직전 3회와 최근 3회 평균 비교':'첫 시험 대비 최근 시험'],['과제 제출',m.submitted+'/'+m.homework,'건','기한 초과 미제출 '+m.missing+'건'],['출석률',fmt(m.attendance),'%','출석 기록 기준 · 지각 포함']])}<section class="report-section"><h3>성적의 흐름</h3>${trendChart(m)}</section><section class="report-section"><h3>단원별 학습 결과</h3>${Object.keys(units).length?`<div class="unit-list">${Object.entries(units).sort((a,b)=>avg(a[1])-avg(b[1])).map(([k,v])=>`<div class="unit-row"><span>${esc(k)}</span><div class="unit-track"><i style="width:${avg(v)}%"></i></div><strong>${fmt(avg(v))}점</strong><small>${v.length}회</small></div>`).join('')}</div>`:empty('단원별 결과가 없습니다.')}</section><section class="report-section"><h3>시험별 상세 기록</h3>${simpleTable([{key:'date',label:'날짜',render:r=>dateText(r.exam.exam_date,true)},{key:'title',label:'시험',render:r=>esc(r.exam.title)},{key:'class',label:'강좌',render:r=>esc(getClass(r.exam.class_id).name)},{key:'score',label:'점수',render:r=>`<strong>${fmt(r.score)}</strong> / ${r.exam.max_score}`},{key:'homework_grade',label:'과제 검사',render:r=>r.exam.lesson_id?esc(gradeLabel((S.data.feedback||[]).find(f=>f.lesson_id===r.exam.lesson_id&&f.student_id===id)?.homework_grade,r.exam.class_id,r.exam.lesson_id)):'—'},{key:'mean',label:'반 평균',render:r=>fmt(S.data.exam_stats[r.exam_id]?.mean)},{key:'comment',label:'코멘트',render:r=>esc(r.comment)||'—'}],[...m.scored].reverse())}</section><section class="report-section"><h3>선생님의 코멘트</h3>${feedbackList(id)}</section><footer class="report-footer">${esc(loginDesign.academy_name||C.BRAND||'미래탐구')} · ${dateText(today(),true)} 발행</footer></article>`}
function renderReports(){const student=isFamily();$('#main').innerHTML=head('학습 리포트',student?'성적과 과제, 수업 태도로 확인하는 배움의 변화.':'선생님의 기준에 해당하는 학생을 놓치지 않도록.',student?btn('인쇄 · PDF 저장','print-report','','','print'):btn('기준 저장','save-criteria','','','check'))+context({view:!student})+(student?studentReportHTML(childID()):`<section class="criteria-panel"><div class="criteria-title"><strong>${icon('filter',16)} 관리대상 기준</strong><select id="criteria-logic"><option value="any" ${S.criteria.logic==='any'?'selected':''}>한 가지라도 해당</option><option value="all" ${S.criteria.logic==='all'?'selected':''}>선택한 조건 모두 해당</option></select></div><div class="criteria-fields">${[['average','averageOn','평균','점 미만',S.criteria.average],['drop','dropOn','성적 하락','점 이상',S.criteria.drop],['missing','missingOn','기한 초과 미제출','건 이상',S.criteria.missing],['absence','absenceOn','결석','회 이상',S.criteria.absence]].map(([key,on,label,suffix,n])=>`<label class="criterion"><input type="checkbox" data-criterion="${on}" ${S.criteria[on]?'checked':''}><span>${label}</span><input type="number" min="0" step="1" data-criterion="${key}" value="${n}"><span>${suffix}</span></label>`).join('')}</div><div class="criteria-bottom"><label>성적 조건 최소 응시 <input type="number" min="1" max="100" data-criterion="minimum" value="${S.criteria.minimum}">회</label><label class="check-label"><input type="checkbox" data-criterion="currentOnly" ${S.criteria.currentOnly?'checked':''}>현재 재원만</label><label class="check-label"><input type="checkbox" data-criterion="only" ${S.criteria.only?'checked':''}>해당 학생만 보기</label><small>성적 하락: 6회 이상은 최근 3회와 직전 3회 평균, 그 미만은 첫 시험과 최근 시험 비교</small></div></section><div id="grid-zone"></div>`);if(!student)renderGridZone()}
