function passwordModal(){modal('비밀번호 변경',`<form id="password-form">${fieldsHtml([{key:'current',label:'현재 비밀번호',type:'password',required:true,wide:true,maxlength:200},{key:'new',label:'새 비밀번호',type:'password',required:true,wide:true,maxlength:200},{key:'confirm',label:'새 비밀번호 확인',type:'password',required:true,wide:true,maxlength:200}])}</form>`,btn('취소','close-modal')+btn('비밀번호 변경','save-editor','','primary','check'));M.isPassword=true;$('#password-form [name=current]').autocomplete='current-password';$('#password-form').onsubmit=e=>{e.preventDefault();M?.save?.()};M.save=async()=>{if(!$('#password-form').reportValidity())return;const d=collect();if(d.new!==d.confirm)return errorBox('새 비밀번호가 서로 다릅니다.');try{const r=await api('/api/change-password',{method:'POST',body:{current:d.current,new:d.new,confirm:d.confirm}});clearClientCaches();S.token=r.token;S.user=r.user;store.set('mirae-v2-session',r.token);closeAll();await reload(true);toast('비밀번호를 변경했습니다.')}catch(e){errorBox(e.message)}}}

