 navigate:b=>navigate(b.dataset.view),new:()=>S.view==='parents'?createParentModal():S.view==='students'?registration():openEditor(), 'new-lesson':()=>openEditor('lessons'), edit:b=>openEditor(S.view,b.dataset.id),
