const NAV_GROUPS=[['tasks','할일','file',['tasks']],['students','학생관리','students',['students','student_accounts','parents','parent_phones','transfers']],['courses','강좌관리','classes',['classes','course_reports','consultations','reports','makeups']],['attendance','출결관리','calendar',['attendance','attendance_book','attendance_overview']],['common','공통관리','consultations',['sms','push','push_status','communications','login_history','detail_settings']],['operations','운영관리','settings',['appearance','oversight','makeup_overview','accounts','audit','ranks']],['boards','게시판','file',['staff_resources','updates']],['extra','추가 기능','accounts',['school_login']]];
function sidebarNavigation(nav){const item=([k,label,ic])=>`<button class="nav-item ${S.view===k?'active':''}" data-action="navigate" data-view="${k}">${icon(ic)}<span>${esc(titleFor(k))}</span>${MiraePlatform?.boardCount(k)?`<b class="count board-count" data-board-count="${k}">${MiraePlatform.boardCount(k)}</b>`:''}${k==='consultations'&&consultUnreadCount()?`<span class="count">${consultUnreadCount()}</span>`:''}</button>`;if(isFamily())return '<nav aria-label="주 메뉴">'+nav.map(item).join('')+'</nav>';S.openNavGroups||=new Set();const groupOf=key=>NAV_GROUPS.find(g=>g[3].includes(key))?.[0];if(S.lastNavView!==S.view){const active=groupOf(S.view);S.openNavGroups=new Set(active?[active]:[]);S.lastNavView=S.view}if(S.openNavGroups.size>1)S.openNavGroups=new Set([S.openNavGroups.values().next().value]);return '<nav class="grouped-nav" aria-label="주 메뉴">'+nav.filter(n=>n[0]==='dashboard').map(item).join('')+NAV_GROUPS.map(([id,label,ic,keys])=>{const children=keys.map(k=>nav.find(n=>n[0]===k)).filter(Boolean);if(!children.length)return '';const open=S.openNavGroups.has(id);return `<section class="nav-group ${open?'is-open':''}"><button class="nav-group-toggle ${keys.includes(S.view)?'contains-active':''}" data-action="nav-group" data-group="${id}" aria-expanded="${open}" aria-controls="nav-group-${id}">${icon(ic)}<span>${label}</span>${id==='boards'&&(MiraePlatform.boardCount('updates')+MiraePlatform.boardCount('staff_resources'))?`<b class="count board-count" data-board-count="boards">${MiraePlatform.boardCount('updates')+MiraePlatform.boardCount('staff_resources')}</b>`:''}${icon('chevron',13)}</button><div class="nav-group-items ${open?'is-open':''}" id="nav-group-${id}" aria-hidden="${!open}" ${open?'':'inert'}><div class="nav-group-inner">${children.map(item).join('')}</div></div></section>`}).join('')+'</nav>'}
async function personalRPC(action,data={}){const auth=await MiraePush.ensureSession();return db.rpc('mirae_personal_settings',{p_session:auth.session,p_action:action,p_data:data})}
async function openPersonalSettings(){document.body.classList.remove('menu-open');$('.sidebar')?.classList.remove('open');const u=S.user,views=accessibleNav().filter(([k])=>!['messenger','parent_phones','settings'].includes(k));modal('개인 설정',`<div class="personal-settings"><div class="account-summary"><span class="avatar">${esc(u.name?.slice(-2)||'M')}</span><div><strong>${esc(u.name)}</strong><small>${esc(u.login_id||'')}</small></div></div><div class="personal-account-actions">${btn('아이디 변경','change-login-id','','','edit')}${btn('비밀번호 변경','change-password','','','accounts')}</div><form data-personal-form><label>전화번호<input class="input" name="phone" type="tel" autocomplete="tel" maxlength="24" placeholder="010-0000-0000" disabled></label><label>모바일 앱 첫 화면<select class="input" name="start_view" aria-describedby="start-screen-note" disabled>${views.map(([k])=>`<option value="${k}">${k==='attendance'?'실시간 출결':esc(titleFor(k))}</option>`).join('')}</select></label><p class="start-screen-note" id="start-screen-note">모바일 앱에만 적용됩니다. PC는 오늘의 클래스로 시작합니다.</p><button class="btn primary" type="submit" disabled>저장하기</button><p data-personal-status role="status">설정을 불러오는 중</p></form>${!isFamily()&&(can('sms')||can('attendance_notify')||can('mswitch_contact'))?'<button type="button" class="personal-link" data-action="mswitch-link"><span>엠스위치 연동</span><span>›</span></button>':''}</div>`,btn('닫기','close-modal'));const editor=M,node=editor.node,form=node.querySelector('form'),status=node.querySelector('[data-personal-status]');try{const value=await personalRPC('read');if(!node.isConnected)return;let expected=value.phone;form.phone.value=value.phone||'';form.start_view.value=views.some(([k])=>k===value.start_view)?value.start_view:views.some(([k])=>k==='attendance')?'attendance':views.some(([k])=>k==='dashboard')?'dashboard':views[0]?.[0]||'';form.querySelectorAll('input,select,button').forEach(x=>x.disabled=false);status.textContent='';form.onsubmit=async e=>{e.preventDefault();if(editor.busy||!form.reportValidity())return;editor.busy=true;const b=form.querySelector('button');b.disabled=true;try{const result=await personalRPC('save',{phone:form.phone.value,expected_phone:expected,start_view:form.start_view.value});expected=result.phone;S.user.preferences={...S.user.preferences,start_view:result.start_view};const a=accountRow(S.user);if(a)a.preferences={...a.preferences,start_view:result.start_view};S.base.user=S.user;MiraeDrafts.clear(editor.node);editor.dirty=false;status.textContent='저장완료';window.MiraeMessenger.refresh?.();toast('저장완료')}catch(e){status.textContent=/CHAT_PHONE_CHANGED/.test(e.message)?'전화번호가 다른 화면에서 변경되었습니다. 닫았다가 다시 열어 주세요.':e.message}finally{editor.busy=false;b.disabled=false}}}catch(e){if(node.isConnected)status.textContent='개인 설정을 불러오지 못했습니다. 관리자에게 확인해 주세요.'}}
async function renderDetailSettings(){const main=$('#main');main.innerHTML=head('상세 설정')+'<div class="detail-settings-panels"></div>';const panels=main.querySelector('.detail-settings-panels');const panel=(title,id)=>{const d=document.createElement('details');d.className='settings-fold';d.innerHTML='<summary>'+esc(title)+'</summary><div class="settings-fold-body" id="'+id+'"></div>';panels.append(d);return d};if(can('report_template')){const d=panel('공통 알림 문구','common-notice-settings');d.open=true;MiraeReportNotify.settings(d.querySelector('div'));}if(isSuper()||can('pc_settings')){const d=panel('내 PC · 모바일 연결','pc-connection-settings');MiraePC.mountSettings(d.querySelector('div'));}if(isSuper()){const tn=panel('타임넷 공통 연결 · 최고관리자','timenet-settings');tn.addEventListener('toggle',()=>{if(tn.open&&!tn.dataset.loaded){tn.dataset.loaded='true';mountTimenetSettings()} });const data=panel('데이터 · 설치','data-install-settings');data.querySelector('div').innerHTML='<p><a href="setup.html" target="_blank" rel="noopener">연결 설정 열기</a></p><div class="settings-actions"><button class="btn" data-backup>전체 백업 받기</button><label class="btn">백업 복원<input type="file" data-restore accept=".json" hidden></label></div>';data.querySelector('[data-backup]').onclick=async()=>{try{const value=await api('/api/v2/backup');downloadBlob(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),'mirae-backup-'+today()+'.json')}catch(e){toast(e.message,true)}};data.querySelector('[data-restore]').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(!confirm('선택한 백업으로 데이터를 복원할까요? 현재 백업을 먼저 받아 두세요.'))return;const restored=await api('/api/v2/restore',{method:'POST',body:{data:JSON.parse(await f.text())}});if(!restored.requires_login)await reload(true);toast('복원완료 · 다시 로그인해 주세요.')}catch(e){toast(e.message,true)}finally{e.target.value=''}};const push=panel('앱 · 알림 설정','push-admin-settings');push.addEventListener('toggle',()=>{if(push.open&&!push.dataset.loaded){push.dataset.loaded='true';MiraePushUI.settings(push.querySelector('div'))}});}}
function ensureConsultDates(){if(S.consultOwner!==S.user.id){const end=today(),[y,m,d]=end.split('-').map(Number),last=new Date(y,m-1,0).getDate();S.consultOwner=S.user.id;S.consultEnd=end;S.consultStart=new Date(y,m-2,Math.min(d,last),12).toLocaleDateString('sv-SE');}}
