async function deleteConsultations(ids){if(!can('consultation_delete')||!ids.length)return;const rows=ids.map(id=>S.data.consultations.find(c=>c.id===id)).filter(Boolean);if(!rows.length)return;if(!confirm(rows.length+'건의 상담 신청 기록을 삭제할까요? 삭제한 기록은 목록에서 사라집니다.'))return;const editor=M;if(editor?.busy)return;if(editor)editor.busy=true;try{const auth=await MiraePush.ensureSession();await db.rpc('mirae_consultations_manage',{p_session:auth.session,p_action:'delete',p_data:{rows:rows.map(c=>({id:c.id,version:c.version}))}});S.selected.clear();if(editor)closeModal(true);inflightReads.clear();await reload();toast('삭제완료')}catch(e){toast(/CONSULTATION_CHANGED/.test(e.message)?'상담 내용이 변경되었습니다. 새로고침 후 다시 확인해 주세요.':e.message,true)}finally{if(editor)editor.busy=false}}
async function showParents(){const owner=S.user.id,generation=++S.generation;S.loading=false;try{S.parents=(await localAPI('/api/parents')).rows;if(S.view!=='parents'||S.user?.id!==owner||generation!==S.generation)return;render();const value=await api('/api/parents');if(S.view!=='parents'||S.user?.id!==owner||generation!==S.generation)return;S.parents=value.rows;drawGrid()}catch(e){if(S.user?.id===owner&&S.view==='parents'){render();toast('학부모 목록을 새로 확인하지 못했습니다. 새로고침을 눌러 주세요.',true)}}}

