 modal('학부모 정보 수정',`<form id="parent-edit-form">${fieldsHtml([{key:'name',label:'학부모 이름',required:true,maxlength:100},{key:'phone',label:'연락처',type:'tel',required:true,maxlength:20},{key:'login_id',label:'로그인 아이디',required:true,maxlength:100}],p)}</form>`,btn('취소','close-modal')+btn('저장','save-editor','','primary','check'));
