// v1.6 teaching workspace. Submission review and homework evaluation stay separate.
const HW_SCHEMES={numeric:'숫자',alphabet:'알파벳'};
const homeworkMode=s=>['alphabet','abcdf','korean','text'].includes(s)?'alphabet':'numeric';
const homeworkMax=(cid,l=null)=>Number(l?.homework_max_score)||Number((getClass(cid).homework_scheme||'').replace('points',''))||100;
const schemeOf=cid=>getClass(cid).homework_scheme||'numeric';
function gradeValue(scheme,value,maximum=100){
 const text=String(value??'').trim();if(!text)return null;
 if(homeworkMode(scheme)==='numeric'){const n=Number(text),max=scheme.startsWith('points')?Number(scheme.slice(6)):maximum;if(!/^\d{1,6}(?:\.\d{1,2})?$/.test(text)||!Number.isFinite(n)||n<0||n>max)throw Error(`과제 평가는 0~${max}점, 소수 둘째 자리까지 입력해 주세요.`);return String(n)}
 if(['abcdf','alphabet'].includes(scheme)){const v=text.toUpperCase();if(!['A','B','C','D','F'].includes(v))throw Error('A·B·C·D·F 중에서 선택해 주세요.');return v}
 if(scheme==='korean'&&!['수','우','미','양','가'].includes(text))throw Error('수·우·미·양·가 중에서 선택해 주세요.');
 if(scheme==='text'&&text.length>500)throw Error('과제 평가는 500자까지 입력해 주세요.');return text;
}
function gradeInput(scheme,value,attrs='',disabled=false,maximum=100){
 const v=value??'',a=`${attrs} ${disabled?'disabled':''} aria-label="과제 평가"`;
 if(['abcdf','alphabet','korean'].includes(scheme))return `<select ${a}><option value="">미입력</option>${(['abcdf','alphabet'].includes(scheme)?['A','B','C','D','F']:['수','우','미','양','가']).map(x=>`<option ${x===v?'selected':''}>${x}</option>`).join('')}</select>`;
 return `<input ${a} type="${scheme==='text'?'text':'number'}" ${scheme==='text'?'maxlength="500"':`min="0" max="${scheme.startsWith('points')?scheme.slice(6):maximum}" step="0.01"`} value="${esc(v)}" placeholder="미입력">`;
}
function gradeLabel(value,cid,lid){const l=D.lessons.find(l=>l.id===lid);return value===null||value===undefined||value===''?'미입력':String(value)+(homeworkMode(l?.homework_scheme||schemeOf(cid))==='numeric'?' / '+homeworkMax(cid,l)+'점':'')}
function commentBlock(value){
 const text=String(value||'');if(!text)return '<span class="muted">—</span>';
 const long=text.length>180||text.split('\n').length>3,id='comment-'+uid();
 return `<div class="teacher-comment"><div id="${id}" class="comment-body ${long?'is-collapsed':''}">${esc(text)}</div>${long?`<button type="button" class="comment-toggle" data-action="toggle-comment" aria-controls="${id}" aria-expanded="false">…자세히 보기</button>`:''}</div>`;
}
function staffName(id){return (S.base.teachers||[]).find(t=>t.id===id)?.name||(S.accounts||[]).find(t=>t.id===id)?.name||'—'}
