 $('[data-action=paste-scores]',node).onclick=()=>{modal('성적 · 과제 평가 붙여넣기',`<p class="muted">학생명 또는 원생번호 / 시험 점수 / 시험 코멘트 / 과제 평가 순서입니다. 동명이인은 원생번호로 구분해 주세요.</p><textarea id="score-paste" rows="7" class="paste-box" placeholder="원생번호&#9;점수&#9;코멘트&#9;과제 평가"></textarea>`,btn('입력표에 반영','apply-score-paste','','primary','check'),{wide:true});$('[data-action=apply-score-paste]',M.node).onclick=()=>{try{const changes=[];for(const r of parseDelimited($('#score-paste').value)){if(['학생명','이름','원생번호'].includes(r[0]?.trim()))continue;const found=draft.filter(d=>d.s.student_no===r[0]?.trim()||d.s.name===r[0]?.trim());if(found.length!==1)throw Error(r[0]+': 현재 학생 한 명으로 식별되지 않습니다. 원생번호를 사용해 주세요.');const score=String(r[1]??'').trim(),absent=['결석','미응시','불참'].includes(score);if(score&&!absent&&(!Number.isFinite(Number(score))||Number(score)<0||Number(score)>exam.max_score))throw Error(r[0]+': 시험 점수를 확인해 주세요.');if(!linked&&r[3]?.trim())throw Error('과제 평가를 붙여넣기 전에 수업 기록을 연결해 주세요.');const grade=r[3]===undefined?found[0].grade:gradeValue(linkedLesson?.homework_scheme||scheme,r[3],homeworkMax(exam.class_id,linkedLesson));changes.push([found[0],{score:absent?'':score,absent,comment:r[2]??found[0].comment,grade:grade??''}])}changes.forEach(([d,c])=>Object.assign(d,c));closeModal(true);draw();editor.dirty=true}catch(e){errorBox(e.message)}}};
