 const form=$('#design-form'),canvas=$('#design-live-canvas');node.dataset.modelKey='login-design';node._draftCapture=()=>{collectLinks();const values={};for(const x of form.elements)if(x.name)values[x.name]=x.value;MiraeDrafts.setModel('login-design',{...draft,...values,buttons:links,opening:openingDraft})};form.onsubmit=e=>{e.preventDefault();if(form.reportValidity())node.querySelector('[data-action=design-save]')?.click()};const device=$('.design-preview-device',node);device.value=previewMobile?'mobile':'pc';device.onchange=()=>{previewMobile=device.value==='mobile';draw()};
 function collectLinks(){links=$$('.promo-edit-row',form).map(row=>({label:$('[data-promo-label]',row).value,url:$('[data-promo-url]',row).value}))}
