 $('[data-action=design-save]',node).onclick=async()=>{const b=$('[data-action=design-save]',node);if(b.disabled)return;collectLinks();draw();b.disabled=true;try{validateDesign(draft);const r=await api('/api/admin/login-design',{method:'POST',body:{design:draft,revision}});revision=r.revision;loginDesign=safeDesign(r.design);designRevision=revision;window.MiraeOpening.configure(loginDesign.opening);themeDesign();$('#design-save-status').textContent='저장완료';toast('로그인 화면과 오프닝을 저장했습니다.');}catch(e){$('#design-save-status').textContent=e.message;toast(e.message,true)}finally{b.disabled=false}};
