// v2.4 UI and policy rules. Data access remains the existing simple RPC model.
function can(cap,a=S.user){if(['parent','student'].includes(a?.role)){if(cap==='makeups')return S.base?.makeup_summary?.assigned===true;return ['dashboard','classes','lessons','exams','consultations','videos','reports'].includes(cap)}return window.MiraeRoles.allows(a,cap,D.settings?.role_policy||S.base.role_policy)}
function requireCap(a,cap){if(!can(cap,a))throw Error('이 기능을 사용할 권한이 없습니다.')}
function isSuper(){return S.user?.role==='admin'}
const EDIT_CAP={students:'student_edit',parents:'parent_edit',classes:'class_edit',lessons:'lesson_edit',exams:'exam_edit',scores:'exam_edit',feedback:'lesson_edit',enrollments:'student_edit',consultations:'consultation_edit',videos:'video_edit',accounts:'staff_manage'};
function actionCap(act){if(act==='new'||act==='edit'||act==='import'||act==='save-grid'||act==='toggle-edit'||act==='bulk-status')return EDIT_CAP[S.view];return({'student-report':'reports','print-report':'reports','parent-detail':'parents','lesson-detail':'lessons','exam-detail':'exams','play-video':'videos','consult-detail':'consultations','syllabus-view':'classes','new-lesson-exam':'exam_edit','link-exam-lesson':'exam_edit','paste-scores':'exam_edit','apply-score-paste':'exam_edit','clear-class-grades':'lesson_edit','confirm-clear-grades':'lesson_edit','mark-roster-present':'lesson_edit','family-edit':'parent_edit','family-password':'parent_edit','new-lesson':'lesson_edit','edit-lesson':'lesson_edit','lesson-feedback':'lesson_edit','duplicate-lessons':'lesson_edit','edit-student':'student_edit','manual-student':'student_edit','import-students':'student_edit','add-enrollment':'student_edit','enrollment-edit':'student_edit','parent-for-student':'parent_edit','family-create':'parent_edit','parent-edit':'parent_edit','parent-password':'parent_edit','edit-exam':'exam_edit','score-entry':'exam_edit','edit-video':'video_edit','timenet-refresh':'timenet','check-sheet':'timenet','roster-picker':'student_edit','export':'export','syllabus-edit':'syllabus_edit'})[act]}
function rankName(a){return window.MiraeRoles.rank(a,S.base.role_policy||D.settings?.role_policy).name}
function canEditDesign(a=S.user){return can('login_design',a)}
function accessibleNav(){if(isFamily())return NAV.filter(([k])=>['dashboard','classes','lessons','exams','consultations','videos','reports'].includes(k)||k==='makeups'&&can('makeups'));return NAV.filter(([k])=>!['lessons','exams','videos','settings'].includes(k)).filter(([k])=>k==='tasks'?true:k==='transfers'?(can('student_transfer')||can('class_edit')):k==='attendance_book'?can('attendance'):k==='login_history'?(can('login_history_all')||can('login_history_own')):k==='push_status'?canViewAlarmStatus():k==='detail_settings'?(isSuper()||can('report_template')||can('pc_settings')):['staff_resources','school_login','course_reports','messenger','updates'].includes(k)?true:['settings','ranks'].includes(k)?isSuper():can(({accounts:'staff_manage',appearance:'login_design',push:'push_send',parent_phones:'mswitch_contact',student_accounts:'students'})[k]||k))}
function mobileNavHTML(){if(!window.MiraePC?.isMobile||isFamily())return'';const permitted=accessibleNav();const picks=['attendance','students','classes'].filter(v=>permitted.some(([k])=>k===v));return'<nav class="mobile-app-nav" aria-label="빠른 메뉴">'+picks.map(v=>`<button data-action="navigate" data-view="${v}" class="${S.view===v?'active':''}">${icon(v==='attendance'?'calendar':v,18)}<span>${v==='attendance'?'출결':v==='students'?'학생':'강좌'}</span></button>`).join('')+'<button data-action="mobile-menu">'+icon('menu',18)+'<span>더보기</span></button></nav>'}
function guardRoute(a,route,write){if(route==='/api/contact/matched'||route==='/api/contact/matched-batch'){requireCap(a,'mswitch_contact');return}
 if(route==='/api/makeups/stats')return;
 if(route.startsWith('/api/makeups/')){if(a.role!=='parent'&&a.role!=='student')requireCap(a,write?'makeup_manage':'makeups');return}
 if(['parent','student'].includes(a.role)){if(!['/api/workspace','/api/bootstrap','/api/data','/api/me','/api/logout','/api/change-password','/api/change-login-id','/api/consultations','/api/video-progress'].includes(route)&&!/^\/api\/(classes\/[^/]+\/syllabus|consultations\/[^/]+\/cancel)$/.test(route))throw Error('조회할 수 없는 메뉴입니다.');return;}
 if(route==='/api/settings'||route.startsWith('/api/v2/')||route==='/api/ranks'){assertAdmin(a);return}
 if(route==='/api/accounts'){requireCap(a,'staff_manage');return}
 if(route==='/api/audit'){requireCap(a,'audit');return}
 if(route==='/api/oversight'){requireCap(a,'oversight');return}
 if(route==='/api/mswitch/credentials'){if(!can('sms',a)&&!can('attendance_notify',a)&&!can('mswitch_contact',a))throw Error('엠스위치를 사용할 권한이 없습니다.');return}
 if(route==='/api/mswitch/local-parents'){requireCap(a,'sms');return}
 if(route.startsWith('/api/timenet/')){if(['/api/timenet/cache','/api/timenet/pc-config'].includes(route))requireCap(a,'timenet');else if(!can('students',a)&&!can('timenet',a))throw Error('학생 명단 열람 권한이 없습니다.');return}
 if(route==='/api/attendance/overview'){requireCap(a,'attendance_overview');return}if(route.startsWith('/api/attendance/')){requireCap(a,'attendance');if(write)requireCap(a,['/claim','/retry','/report'].some(k=>route.endsWith(k))?'attendance_notify':route.endsWith('/link')?'attendance_notify':'attendance_edit');return}
 if(route.startsWith('/api/manage/')){requireCap(a,EDIT_CAP[route.split('/')[3]]||'student_edit');return}
 if(route==='/api/lesson-record'){requireCap(a,'lesson_edit');return}
 if(/^\/api\/exams\/.+\/results$/.test(route)){requireCap(a,'exam_edit');return}
 if(route.startsWith('/api/parents')||/^\/api\/students\/.+\/parent$/.test(route)){requireCap(a,write?'parent_edit':'parents');return}
 if(/^\/api\/classes\/.+\/syllabus$/.test(route)){requireCap(a,write?'syllabus_edit':'classes');return}
 if(route.endsWith('clear-homework-grades'))requireCap(a,'lesson_edit');
}
function guardSubject(a,route,body,path){const A=window.MiraeSubject;if(A.scope(a)==='all')return;const u=new URL(path,'https://browser.invalid'),visible=A.scoped(D,a);let cid=body.class_id||body.lesson?.class_id||u.searchParams.get('class_id');const parts=route.split('/');if(parts[2]==='classes'&&parts[3])cid=parts[3];if(parts[2]==='exams'&&parts[3])cid=D.exams.find(e=>e.id===parts[3])?.class_id;if(cid)A.assertClass(D,a,cid);const sid=body.student_id||(parts[2]==='students'?parts[3]:null);if(sid&&!visible.students.some(s=>s.id===sid))throw Error('지정된 과목의 학생만 관리할 수 있습니다.');if(parts[2]==='parents'&&parts[3]&&!['create','search'].includes(parts[3])&&!visible.parents.some(p=>p.id===parts[3]))throw Error('지정된 과목의 학부모만 열 수 있습니다.');}

function parentState(s){const p=(S.base.parents||[]).find(p=>p.id===s.parent_id);return !p?{label:'미배정',tone:'danger'}:p.status!=='active'?{label:'비활성 · '+p.name,tone:'warn'}:{label:'연결됨 · '+p.name,tone:'ok'}}
function parentConnection(s){const state=parentState(s);return'<span class="connection-state '+state.tone+'">'+esc(state.label)+'</span>'+(can('parent_edit')?btn('배정','parent-for-student',`data-id="${s.id}"`,'ghost sm'):'')}
function smsConnection(s){const A=window.MiraeAttendanceCore,r=window.MiraeSMS?.cachedRoster,source=A.sourceStudent(D,s,S.user),hasPhone=source.parent_phones.some(p=>String(p).replace(/\D/g,'').length>=9);let tone='warn',label='문자 연결 확인중';if(r){const m=A.matchStudent(source,r,D.studentLinks?.find(l=>l.owner_id===S.user.id&&l.student_id===s.id),r.account_username);if(['auto','manual'].includes(m.kind)){tone='ok';label='문자 연결됨'}else if(m.kind==='no_phone'||!hasPhone&&!(m.candidates||[]).some(t=>t.parent_phones.some(p=>p.length>=9))){tone='danger';label='학부모 번호 없음'}else label='문자 연결 필요'}else if(!hasPhone){tone='danger';label='학부모 번호 없음'}return'<span class="connection-state '+tone+'">'+esc(label)+'</span>'}
window.addEventListener('mirae-mswitch-roster',()=>{if(S.user&&S.view==='students')drawGrid()});
function sharedDirectory(rows){const map=new Map();for(const r of rows){const old=map.get(r.student_no);if(!old||String(r._cached_at||'')>=String(old._cached_at||''))map.set(r.student_no,r)}return [...map.values()]}
let directoryTimer=null,directoryPolling=false;
function directoryAge(){const stamp=S.base.timenet_meta?.updated_at;if(!stamp)return'아직 불러온 명단이 없습니다.';const seconds=Math.max(0,Math.floor((Date.now()-Date.parse(stamp))/1000));return(seconds<60?seconds+'초':seconds<3600?Math.floor(seconds/60)+'분':Math.floor(seconds/3600)+'시간')+' 전 명단'}
function paintDirectoryAge(){for(const node of document.querySelectorAll('[data-directory-age]'))node.textContent=directoryAge()}
function startDirectorySync(){if(directoryTimer||!S.user||isFamily()||!can('students')&&!can('timenet'))return;directoryTimer=setInterval(async()=>{paintDirectoryAge();if(directoryPolling||!S.user||isFamily())return;directoryPolling=true;const owner=S.user.id;try{const meta=await api('/api/timenet/meta');if(owner!==S.user?.id)return;if(meta.updated_at!==S.base.timenet_meta?.updated_at){S.base.timenet_meta=meta;directoryCache=null;paintDirectoryAge();window.dispatchEvent(new Event('mirae-directory-updated'))}}catch{}finally{directoryPolling=false}},5000)}
function stopDirectorySync(){clearInterval(directoryTimer);directoryTimer=null;directoryPolling=false}
